options.getOption:
const apps = {
  grafana: { name: 'Grafana', color: '#F2495C' },
  netbird: { name: 'NetBird', color: '#E0B6EC' },
  proxmox: { name: 'Proxmox', color: '#F2CC0C' },
  account_portal: { name: 'Account portal', color: '#FFCB7D' },
  managed_unix: { name: 'Managed Unix', color: '#FF9830' },
};
const required = ['App', 'App ID', 'Unique Users', 'Authentications'];
const fieldName = (field) => field.config?.displayName || field.name;
const frames = context.panel.data.series.filter((series) => required.every((name) => series.fields.filter((field) => fieldName(field) === name).length === 1));
const frame = frames.length === 1 ? frames[0] : undefined;
const fields = frame ? Object.fromEntries(required.map((name) => [name, frame.fields.find((field) => fieldName(field) === name).values])) : {};
const valid = frame && required.every((name) => fields[name].length === fields.App.length) && Array.from(fields.App).every((name) => typeof name === 'string') && Array.from(fields['App ID']).every((id) => typeof id === 'string' && id.length > 0);
const rows = valid ? Array.from(fields.App, (name, index) => {
  const key = name.toLowerCase().replaceAll(' ', '_');
  const app = Object.hasOwn(apps, key) ? apps[key] : { name, color: '#8AB8FF' };
  return { ...app, count: fields.Authentications[index], users: fields['Unique Users'][index] };
}) : [];
const theme = context.grafana.theme;
const textColor = theme.colors.text.primary;
const labelColor = theme.isDark ? '#FFFFFF' : textColor;

if (rows.length === 0 || rows.some((row) => !Number.isSafeInteger(row.count) || row.count < 0 || !Number.isSafeInteger(row.users) || row.users < 0 || row.users > row.count)) {
  return { graphic: { type: 'text', left: 'center', top: 'middle', style: { text: 'Unavailable', fill: textColor } } };
}

const maximum = Math.max(1, ...rows.map((row) => row.count));
const summary = (row) => `{count|${row.count}}\n{users|${row.users} unique ${row.users === 1 ? 'user' : 'users'}}`;
const detail = (row) => `${row.name}\nAuthentications: ${row.count}\nUnique Users: ${row.users}`;
const track = rows.map(() => maximum);
const carrier = {
  type: 'bar', barGap: '-100%', barWidth: '80%', barMaxWidth: 40,
  data: track, silent: true, z: 3,
  itemStyle: { color: 'transparent' }, tooltip: { show: false }, emphasis: { disabled: true },
};
return {
  animation: false,
  backgroundColor: 'transparent',
  aria: { enabled: true, label: { description: rows.map(detail).join(', ') } },
  grid: { left: 4, right: 4, top: 4, bottom: 4 },
  xAxis: { type: 'value', min: 0, max: maximum, show: false },
  yAxis: { type: 'category', inverse: true, data: rows.map((row) => row.name), show: false },
  legend: { show: false },
  tooltip: {
    trigger: 'axis', renderMode: 'richText', confine: true,
    formatter: (parameters) => detail(rows[parameters[0].dataIndex]),
  },
  series: [
    {
      name: 'Authentications', type: 'bar', barWidth: '80%', barMaxWidth: 40, z: 2,
      showBackground: true, backgroundStyle: { color: theme.colors.background.secondary },
      data: rows.map((row) => ({ value: row.count, itemStyle: { color: row.color, opacity: theme.isDark ? 0.4 : 0.2 } })),
      emphasis: { disabled: true },
    },
    { ...carrier, label: { show: true, position: 'insideLeft', color: labelColor, fontSize: 16, formatter: (parameters) => rows[parameters.dataIndex].name } },
    { ...carrier, label: { show: true, position: 'insideRight', color: labelColor, fontSize: 16, rich: { count: { fontSize: 18, fontWeight: 600, lineHeight: 20 }, users: { fontSize: 12, lineHeight: 14 } }, formatter: (parameters) => summary(rows[parameters.dataIndex]) } },
  ],
};

const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const required = ['Hour', ...days];
const fieldName = (field) => field.config?.displayName || field.name;
const frames = context.panel.data.series.filter((series) => required.every((name) => series.fields.filter((field) => fieldName(field) === name).length === 1));
const frame = frames.length === 1 ? frames[0] : undefined;
const fields = frame ? Object.fromEntries(required.map((name) => [name, frame.fields.find((field) => fieldName(field) === name).values])) : {};
const hours = fields.Hour ? Array.from(fields.Hour, (value) => typeof value === 'string' && /^\d{2}$/.test(value) ? Number(value) : value) : [];
let invalid = !frame || hours.length !== 24 || new Set(hours).size !== 24 || hours.some((hour) => !Number.isInteger(hour) || hour < 0 || hour > 23) || required.some((name) => !fields[name] || fields[name].length !== 24);
const data = [];

if (!invalid) {
  days.forEach((day, weekday) => {
    Array.from(fields[day]).forEach((count, index) => {
      if (count === null || Number.isNaN(count)) {
        return;
      }

      if (!Number.isSafeInteger(count) || count < 0) {
        invalid = true;
      } else {
        data.push([hours[index], weekday, count]);
      }
    });
  });
}
const theme = context.grafana.theme;
const textColor = theme.colors.text.primary;

if (invalid || data.length === 0) {
  return { graphic: { type: 'text', left: 'center', top: 'middle', style: { text: 'Unavailable', fill: textColor } } };
}

const labels = Array.from({ length: 24 }, (_, hour) => String(hour).padStart(2, '0'));
return {
  animation: false,
  backgroundColor: 'transparent',
  aria: { enabled: true },
  grid: { left: 44, right: 8, top: 8, bottom: 48 },
  xAxis: {
    type: 'category', data: labels, name: 'Hour', nameLocation: 'middle', nameGap: 28,
    nameTextStyle: { color: textColor, fontSize: 14 },
    axisLabel: { color: textColor, fontSize: 14, interval: 'auto', hideOverlap: true },
    axisLine: { show: false }, axisTick: { show: false }, splitArea: { show: false },
  },
  yAxis: {
    type: 'category', data: days, inverse: true,
    axisLabel: { color: textColor, fontSize: 14 },
    axisLine: { show: false }, axisTick: { show: false }, splitArea: { show: false },
  },
  legend: { show: false },
  visualMap: {
    show: false, type: 'continuous', dimension: 2, min: 0,
    max: Math.max(1, ...data.map((cell) => cell[2])),
    inRange: { color: theme.isDark ? ['#16283E', '#315F8C', '#8AB8FF'] : ['#EFF6FF', '#5794F2', '#1154A3'] },
  },
  tooltip: {
    trigger: 'item', renderMode: 'richText', confine: true,
    formatter: ({ value }) => `${days[value[1]]} ${labels[value[0]]}:00\nAuthentications: ${value[2]}`,
  },
  series: [{
    name: 'Authentications', type: 'heatmap', coordinateSystem: 'cartesian2d', data,
    label: { show: false },
    itemStyle: { borderWidth: 1, borderColor: theme.colors.background.primary },
    emphasis: { itemStyle: { borderWidth: 2, borderColor: textColor } },
  }],
};
